  `,G.appendChild(Q),Jt=Q.querySelector("#lab-seed"),Q.querySelector("#lab-morale").addEventListener("change",s=>{Me=Math.max(80,Math.min(140,Math.round(Number(s.target.value)||120))),s.target.value=String(Me)}),Q.querySelector("#sim-10").addEventListener("click",()=>Ct(10)),Q.querySelector("#sim-50").addEventListener("click",()=>Ct(50));const n=document.createElement("div");n.className="err-msg lab-err",G.appendChild(n),ie=document.createElement("div"),ie.className="lab-analysis",ie.style.display="none",G.appendChild(ie)}const nn=[{version:"1.26",date:"2026-11-06",title:"战报伤兵一目了然 · 胜率改四档并新增战损比",summary:"战报里每个武将现在同时显示兵力与伤兵，兵力条按剩余 / 伤兵 / 阵亡三段铺开；胜率统计由三档改成「胜利 / 优势平 / 劣势平 / 失败」四档，并多给一个战损比。另外修正了武将阵亡瞬间伤兵的处理，以及准备阶段（战斗开始前）的出手顺序。",groups:[{kind:"新增",items:["「战报」兵力条改成三段：深色是剩余兵力、浅色是伤兵、暗灰是已经阵亡的部分，一眼就能看出这队还有多少能救回来。","「战报」每个武将卡底部改成两块数字：左边当前兵力、右边伤兵；伤兵是 0 也照样占位显示，数字不会忽隐忽现。","「统计胜率」新增战损比：每场按我方阵亡 ÷ 敌方阵亡算一次，再对全部场次取平均；只算阵亡，伤兵与残兵都不计入。"]},{kind:"调整",items:["「统计胜率」由「胜 / 平 / 负」三档改成「胜利 / 优势平 / 劣势平 / 失败」四档：大营被打掉就是胜利或失败，打满回合按剩余兵力分优势平与劣势平，双方完全相同时并入优势平。","武将兵力归零阵亡的那一刻，伤兵池会损失四成（直接转入永久死亡），剩下的六成留在池内、之后不再逐回合损耗；存活武将的伤兵仍按原比例每回合折损。"]},{kind:"修复",items:["准备阶段（战斗开始前）的出手顺序改成与正式回合一致：带上宝物、陈寿特性以及被动、指挥战法提供的速度后重新排序，不再出现「战报开头慢将先动、正式回合却是快将先手」的两套顺序。"]},{kind:"说明",items:["桌面、平板与手机的展示规则一致；安卓包 2.11（versionCode 35）。"]}]},{version:"1.25",date:"2026-11-06",title:"战报两个显示问题修复",summary:"手机上看战报有两处被裁：右侧回合号放不下、只能点到前三回合；简略页只剩一名武将时立绘被放大、底部信息被切掉。两处都已修好，桌面不受影响。",groups:[{kind:"修复",items:["手机「战报详情」：右侧回合号整段可上下滑动，8 回合也能翻到底；「详 / 简 / 上 / 下 / 播」这些控制键固定不动，滑到最后一回合时当前回合号会自动滚进视野。","手机「战报简略」：立绘卡改成按可用高度等比缩放 —— 单将不再被撑大裁掉卡内兵力条，三将仍按原样排布。"]},{kind:"说明",items:["桌面与平板完全不变；安卓包 2.10（versionCode 34）。"]}]},{version:"1.24",date:"2026-11-05",title:"手机端界面重排 · 少滚动，多一屏",summary:"手机上最挤的四块界面重排了：首页队头按钮与下架开关不再占位、战法背包的筛选栏随滚动收起、宝物详情收进底部抽屉、战报详情去掉结果顶栏。桌面与平板完全不变。",groups:[{kind:"优化",items:["手机「配将」页：去掉队头的「部队加成 / 保存预设 / 清空本队」与「显示下架武将」开关，腾出的整行高度全部还给两队面板与武将池。","手机「战法背包」：搜索与品级 / 类别筛选栏向下滚时自动收起、向上滚或回到顶部时自动展开；收起时留一条摘要条，显示当前筛选与数量，点一下立刻展开。","手机「宝物选择」：宝物介绍默认收进底部抽屉，网格一屏能看三四行；点宝物展开详情、点「收起」再折叠，详情看完仍可直接「下一步」。","手机「战报详情」：去掉顶部的平局 / 回合数 / 双方残兵结果条，直接从战报正文开始；胜负与回合数改在底栏左侧常驻，右侧「详 / 简 / 上 / 始」页码按钮放大到手指好点。"]},{kind:"优化",items:["手机「配将」页：势力 / 兵种两行筛默认收成一行摘要（如「势力 全部 · 兵种 全部」），点「筛选 ▾」展开、选完自动保留，武将池再多露一行半。","手机顶栏：「伤害测试 / 教程 / 公告」收进「⋯ 更多」，战报 / 预设 / 战法三项才不再挤在一起。","手机「战法背包」：搜索框聚焦时筛选栏锁定不收起，打字时不会突然弹走；战法说明从一行省略改成两行，距离与发动率看得全。","手机「宝物选择」：抽屉收起状态右把手直接给「下一步」，少点一次。"]},{kind:"说明",items:["以上只作用于手机（触屏横屏与手机竖屏）；桌面与平板保持原样，交互不受影响。"]}]},{version:"1.23",date:"2026-11-05",title:"四件新稀世宝物上线 · 曹仁【平壑拒吴】加强",summary:"山君、天问、镂影、奋髯四件新稀世宝物进池（画像与自带特效都已接上）；曹仁的主战法【平壑拒吴】发动率 35% → 40%。",groups:[{kind:"新增",items:["新稀世宝物四件：山君（长兵·钺）、天问（其他·栻盘）、镂影（剑·匕首）、奋髯（长兵·戟），宝物选择里可直接佩戴。","山君自带【破敌】【骁锐】【虎啸】：虎啸 = 行动时主战法每为自身提供 30% 攻击伤害提升，本回合追击战法发动率 +1%。","天问自带【不移】【天资】【观星】：观星 = 主战法施加的犹豫有 40% 几率额外持续 1 回合。","镂影自带【坚忍】【英才】【穿影】：穿影 = 每造成 4 次攻击伤害，下次行动前对 3 距离内敌军单体补一次 20% 攻击。","奋髯自带【骁锐】【不移】【奋武】：奋武 = 普通攻击伤害提升超过 250% 时，普攻无视规避。"]},{kind:"调整",items:["曹仁·平壑拒吴：发动率 35% → 40%（伤害率 210%、怯战 2 回合不变）。"]},{kind:"说明",items:["四件新宝物的锻造词条池官方尚未放出，目前只能使用自带的三条特效，弹窗里会给出提示。"]}]},{version:"1.22",date:"2026-11-05",title:"武将配置不再丢失 · 详情页可存多套「方案」",summary:"把武将卸回武将池再拖回来，战法 / 加点 / 红度 / 宝物 / 兵种 / 陈寿都还在；武将详情新增「方案」页签，可以把一套配置存成「方案一～六」，随时一键切换。",groups:[{kind:"新增",items:["武将详情新增「方案」页签：把当前配置（战法 / 加点 / 红度 / 宝物 / 兵种 / 陈寿）存成最多 6 套方案。","方案一键套用：同一名武将在不同队伍里可以直接切到事先存好的配置，不用逐项重配。"]},{kind:"优化",items:["武将卸回武将池再上阵，会自动带回上次的配置（战法 / 加点 / 红度 / 宝物 / 兵种 / 陈寿），不再从空白开始。","方案行直接显示「战法 + 加点 + 宝物 + 红度」摘要，存了什么一眼可见。"]},{kind:"说明",items:["武将配置记在本机浏览器；同一名武将的两份配置以最后一次编辑的那份为准。"]}]},{version:"1.21",date:"2026-11-05",title:"顶栏「赛季」下拉上线 · 北伐副本副将机制",summary:"顶栏多了一个「赛季」下拉：常规赛季就是原来的引擎口径；切到「北伐副本」后，每名主将可以再佩戴一名同阵营副将，主将四维按主将 70% + 副将 30% 合成，副将主战法占主将第二战法格。",groups:[{kind:"新增",items:["顶栏新增「赛季」下拉（常规赛季 / 北伐副本），选择会被记住，下次进来还是这个模式。","北伐副本支持佩戴副将：副将须与主将同阵营；等级跟随主将、加点独立分配；副将的兵种 / 宝物 / 陈寿特性 / 拆解战法不生效。","主将四维 = 主将面板 × 70% + 副将面板 × 30%（攻击 / 防御 / 谋略 / 速度逐项计算），携带兵力仍按主将等级与红度。","佩戴副将后，主将详情的第二战法格显示副将主战法，点它直接打开副将详情调加点；主将剩下可自由装配的战法位从 2 个变成 1 个。"]},{kind:"说明",items:["常规赛季下所有计算与之前完全一致；副将配置会留在存档里，切回北伐副本即可继续使用。"]}]},{version:"1.20",date:"2026-11-05",title:"「热门预设」改名「预设」· 热门与我的两组可切换",summary:"顶栏入口和面板标题统一叫「预设」。面板左侧多了「热门预设 / 我的预设」两个页签：热门那一组是随站发布的固定队伍，我的那一组是你自己存的，一次只看一组，每个页签上直接标着条数。",groups:[{kind:"调整",items:["顶栏「热门预设」改名为「预设」，面板标题同步改名。","预设面板左侧新增「热门预设 / 我的预设」切换：一次只看一组，页签上标出各组条数，搜索只作用于当前这一组，不再把两组合并在一个长列表里翻。"]},{kind:"优化",items:["保存红队 / 蓝队、上传截图识别、把热门队伍「另存为我的预设」之后，面板会自动切到「我的预设」并选中刚存下的那一条。","空列表的提示按组给下一步：自己还没有预设时直接说清怎么存，搜不到时提示切到另一组看看。"]}]},{version:"1.19",date:"2026-10-27",title:"免疫指挥全面生效：指挥伤害 · 指挥持续伤害 · 相邻溅射一并免疫",summary:"兀突骨【藤甲突击】和象兵「野性」这类免疫指挥，以前只挡得住战必、反计那几张控制，指挥战法打出来的伤害却照样吃。这一版把口径补齐：凡是指挥类型的效果，落在免疫目标身上一律零效果 —— 允许被选中，但打不出伤害、挂不上状态、也不触发相邻溅射。",groups:[{kind:"修复",items:["免疫指挥的武将不再吃指挥战法的伤害：魏延【奇兵拒北】这类二类指挥的站位伤害、吕蒙【白衣渡江】这类一类指挥延迟到第 3 回合的预存伤害，打上去都是 0 伤，战报只记一条「免疫了指挥战法效果」。","指挥战法的持续伤害同样被免疫：黄月英【匠心不竭】的恐慌不再挂到免疫目标身上，之后也不会跳伤。","指挥战法衍生的相邻溅射一并免疫：XP司马懿【其徐如林】的〈诛杀〉不再对免疫目标结算，同一侧相邻的普通目标照常挨溅射。"]},{kind:"说明",items:["免疫目标仍然会出现在战法的目标列表里（选中照旧、效果不落地），与官方一致。","两者范围不同：藤甲突击只免疫敌方指挥，我方指挥增益（张辽【其疾如风】的连击与速度）照常生效；象兵「野性」是双向的，我方指挥也吃不到。"]}]},{version:"1.18",date:"2026-10-26",title:"谋略持续伤害算进策略战法 · 张姬受击动摇建模",summary:"这一版补的是两处「战报里看得见、账上却没算」的漏洞：恐慌 / 燃烧 / 妖术这类谋略持续伤害现在会被当成「造成策略伤害的战法」来认（筹算、未雨绸缪、其徐如林都认）；张姬【将门虎女】的后段「受到攻击伤害时引发动摇」从没建模变成真结算。",groups:[{kind:"修复",items:["谋略类持续伤害（恐慌 / 燃烧 / 妖术 / 妖术诅咒 / 引燃）现在算作「造成策略伤害的战法」：庞统【密谋定蜀】这类只有持续伤害的战法，主战法发动率会正常吃到宝物【筹算】（5.0%~15.0%），也能触发【未雨绸缪】的再发动。","谋略持续伤害的每一次跳伤都会触发晋·司马懿【其徐如林】的相邻〈诛杀〉（以前只有直接策略攻击才触发），伤害照常计入【其徐如林】统计。动摇（逃兵）与分兵不触发。","【张姬·将门虎女】第三段「1 回合内受到攻击伤害时 80.0% 几率引发一次动摇（伤害率 60.0%）」落地：受击立即结算、不消耗次数、窗口结束移除；同时按官方把首段伤害率修正为 200%。","程昱【审时定计】段一「敌军被施加特殊负面效果前 50.0% 概率使其本回合受到伤害提高 30.0%」此前只认挑衅 / 围困 / 控制，持续伤害类负面（恐慌 / 燃烧 / 妖术 / 妖术诅咒 / 引燃 / 动摇）一次都不判 —— 庞统、程昱组队时持续伤害吃不到这层增伤。现已纳入：施加当刻判定，命中后这份持续伤害按提高后的数值结算。"]},{kind:"说明",items:["持续伤害仍按「施加那一刻」的施法者兵力与谋略结算（连同当时的增减伤与目标属性一起冻结），挂上之后双方兵力、增伤、减伤再怎么变都不改动这份伤害 —— 这是刻意的口径，不是漏算。"]}]},{version:"1.17",date:"2026-10-24",title:"大幅减伤口径重做 · 子战法统计 · 成长率补齐 · 热门预设识图",summary:"这一版把攒在一起的几件事一次说清：「大幅度降低」类减伤不再按 90% 记账；借别人战法的伤害终于算回主战法；未雨绸缪的再发动覆盖光武中兴这类子战法；17 个战法补上缺失的成长率（始计、方圆、锋矢等）；热门预设新增「上传截图识别队伍」和多套新阵容。",groups:[{kind:"修复",items:["「大幅度降低」类减伤改为按极大值（1000%）结算：磐阵善守、西乡武功、百家【息交2】不再被敌方增伤抵掉，最终伤害压到下限的 10%；辕门射戟、十面埋伏、反计之策、迟智难酬、鏖兵卫主等「造成伤害大幅降低」也统一到同一口径。","【未雨绸缪】再发动改为按整棵战法树判定：光武中兴、道行险阻这类伤害藏在子战法里的战法会正常再发动（效果 50%），并补上「该战法造成的伤害无视目标 30.0% 谋略属性」（受谋略，0.15/点，只作用于再发动的那一份）。","含子战法的战法统计修正：【连环计】【河内世泽】借来的战法伤害、次数、恢复都记回主战法（以前恒为杀伤 0），子战法挂的持续伤害后续跳伤同样归父战法。","【沧海】破浪增伤恢复生效：每受到 1 次伤害，本回合造成所有伤害 +10%，最多 10 层；【不屈】改为回合结束清零，与破浪同口径。","成长率补齐 17 个战法：始计 0.15/0.25、方圆 0.085、锋矢 0.10、万箭齐发 0.175、恃强淬锋 0.10、道行险阻 0.30×2、地公将军 0.175×4、守静却敌 0.05、令明负榇 0.175、逆谋 0.10、定军扬威 0.175、国士无双 0.15、截断 0.10、拒盾 0.125×2、迫近 0.125、退避 0.15×2、难知如阴 0.15。","【卫瓘·持节镇西】对月英 / 灵帝 / 吕蒙的一类指挥在结算前正确叠层，不再漏计。","抵御不再吞掉一类指挥的预备控制（战必断金 / 措手不及 / 白衣渡江的目标行动判定）。","【刘徽】流速改为逐回合 6 档（80~150 起，逐回合收敛到 115），不再用旧的线性推定。"]},{kind:"新增",items:["热门预设支持上传截图识别：传「阵容详情」截图自动认三将、红度与三个战法，确认卡核对后存入「我的预设」；同名武将列候选，认不出的如实标注；兵种 / 特性 / 宝物 / 加点不识别，等级一律按 40 级。","热门预设新增多套阵容（含「刘秀·司马懿·司马炎」等满红队伍），数据版本升到 2026-10-16.10。"]},{kind:"优化",items:["详情战报：伤害行显示伤害率与浮动区间，子战法标〈伐谋〉〈火辎〉〈诛杀〉；「大幅度降低」类效果统一写「伤害大幅降低」，不暴露账面数字。","「增减伤统计」弹窗的「伤害降低合计」不再裁到 90%，90% 下限只作用于净合计。"]},{kind:"说明",items:["「大幅度」= 很大的值（1000%），不是 90%：包内受攻击 / 受策略攻击伤害降低槽位统一写 9000，按百分比换算的 90% 会被增伤抵掉。","成长率数值取自 9.2.2 热更包 tb_cfg_skill_detail（值@80 = const + 0.4×intel、百分比成长 = intel/200、点数成长 = intel/20000）。","识图用的是你自己在设置里接入的模型（与 AI 配将同一条通道），不上传第三方服务器。"]}]},{version:"1.16",date:"2026-10-21",title:"未雨绸缪修复：再发动与「无视谋略属性」",summary:"「未雨绸缪」这条战法有两处不对：一是它本该让「下一发造成策略伤害的主动战法」再发动一次，但对伤害藏在子战法里的战法（比如刘秀的光武中兴、道行险阻）完全没反应；二是它缺了官方那句「该战法造成的伤害无视目标 X% 的谋略属性」，战报里也看不出来。两处都按 9.2.2 热更包的数据修好了。",groups:[{kind:"修复",items:["「再发动」判定改成看整棵战法树：光武中兴（伤害在随机派遣的子战法里）、道行险阻（延迟结算）这类此前后续的主动战法也会正常再发动一次，效果按原战法的 50% 结算。","补齐「该战法造成的伤害无视目标 30.0% 的谋略属性（受谋略属性影响）」：谋略 80 时 30.0%，此后每点谋略 +0.15%，只作用在再发动的那一份伤害上。","描述（满级 / 1 级）与战报同步：发动行标注「（未雨绸缪：再次发动，效果 50%）」，伤害行尾标注「无视目标 X% 谋略属性」。","「增减伤统计」弹窗的「伤害降低合计」不再被裁到 90%：减伤本身可以超过 100%，各来源照实合计；90% 的下限保护只作用在「净合计」上（提升 − 降低 低于 −90% 时按 −90% 结算，弹窗会注明已触下限）。"]},{kind:"优化",items:["光武中兴的派遣标注：战报伤害行现在写明这一次走的是哪一路子战法——〈落雷〉〈落石〉〈绝水遏敌〉，状态行同步显示「【光武中兴·落石】」，不用再靠伤害率反推。"]},{kind:"说明",items:["数值取自客户端热更包 tb_cfg_skill_detail 的 21030101（再发动比例 50）与 21130101（18000 + 谋略×30000），量纲与「击势」同一套标定（除数 1000）。","「无视谋略属性」只在再次发动的那一份伤害上生效，第一次正常发动不受影响。"]}]},{version:"1.15",date:"2026-10-21",title:"新武将刘秀 + 汉·曹操按官方数据重做",summary:"本版上线光武帝刘秀（汉·骑·五星，主战法【光武中兴】）与汉阵营曹操的官方数据重做（五星 100804 面板 + 主战法【举义诛暴】）。刘秀的【光武中兴】先为我军兵力最低的友军连续恢复两次兵力，随后在落雷、落石、绝水遏敌三个子战法里随机放一个；我军每次被它治好后还有机会追加一次子战法，一回合里三个子战法都放齐就让敌军全体掉 20 士气。汉·曹操的【举义诛暴】打敌军群体两人并压低四维，还让目标在接下来两次受伤时各有一半概率陷入一种控制。",groups:[{kind:"新增",items:["新武将【刘秀】（汉·骑·五星，统率 3.5，攻击距离 3）：主战法【光武中兴】主动、距离 5、发动率 45%。","【光武中兴】：为我军兵力最低的单体恢复 2 次兵力（每次目标独立判定，恢复率 225% 受谋略成长）；随后对 5 距离内敌军随机发动【落雷】（单体 148% 攻击伤害 + 混乱 1 回合）、【落石】（群体 2 个 92.2% 攻击伤害 + 防御 −5.2）、【绝水遏敌】（群体 2~3 个 230% 攻击伤害 + 无法恢复兵力 1 回合）之一，跳过准备回合。","每当【光武中兴】完成一次恢复，都有 30%（受谋略成长，谋略 95 时约 32%，再乘士气）的几率额外随机发动 1 个子战法。","同一回合内【落雷】【落石】【绝水遏敌】三个都发动过之后，敌军全体士气 −20。","刘秀的二级兵种转换：轻骑兵 / 铁骑兵（与官方武将表一致），配将页可直接选。","刘秀的画像与头像、武将详情、兵种面板、离线配置均已接入。"]},{kind:"调整",items:["汉·曹操按官方数据重做：面板改为五星 100804（攻击 76 / 防御 88 / 谋略 72 / 速度 78，成长 1.48 / 2.32 / 1.38 / 1.16），主战法从【献刀七星】换成【举义诛暴】。","【举义诛暴】：主动、距离 5、发动率 40%，对敌军群体 2 人造成 150% 攻击伤害，并使其攻击、防御、谋略、速度各降 5%（受攻击属性成长、持续 1 回合）。","被【举义诛暴】命中的目标，接下来受到的 2 次伤害里，每次都有 50% 几率陷入怯战 / 犹豫 / 混乱 / 暴走之一，持续 1 回合（同一次施放重复命中只刷新次数，不叠层）。"]},{kind:"说明",items:["刘秀的子战法沿用官方同名战法的数值口径（【落雷】【落石】【绝水遏敌】），但作为子战法跳过准备回合、发动率按 100% 派遣。","汉·曹操的武将 id 未变（沿用旧 id），已有队伍配置不需要重新选择，只是数值与主战法换成官方版本。","以上改动会改变相关阵容的伤害数值，历史战报不会重算。"]}]},{version:"1.14",date:"2026-10-20",title:"战法机制修复（奉令护蜀 / 免疫控制 / 乘间击隙 / 一夫当关 / 始计 / 金鸠）",summary:"本版修好六处战法结算问题：马岱【奉令护蜀】的增伤层与减伤层改为各算各的，下一次普攻吃满全部增伤层、下一次受伤吃满全部减伤层；免疫控制（疾战、凌统【国士无双】洞察等）改为能当场解除身上已有的控制，优先于指挥类控制；【乘间击隙】与增伤冲突时不再整场叠不上层，三层照常出伤且与击势、主动增伤互不冲突；【一夫当关】的减伤改为随防御属性成长（防御 80 时为 50%，每多 1 点防御 +0.375%，到 200 防御约 95%）；【始计】只在前 4 回合生效，第 5 回合起不再发动；再次发动战法（赐剑长驱、正始之变等）现在算作一次真实发动，宝物【金鸠】等「发动战法后」的效果照常结算。",groups:[{kind:"修复",items:["马岱【奉令护蜀】：队友普攻、主动、追击带来的层数现在真的会增伤 / 减伤。下一次普通攻击吃满当时全部增伤层并只清空增伤层，下一次受到任何伤害吃满全部减伤层并只清空减伤层，两者互不干扰，不再「叠到五层才消耗」。","免疫控制：【疾战】的免疫怯战、凌统【国士无双】的洞察现在能当场解除已经落在身上的控制（包括战必断金、措手不及这类指挥控制），不再出现「免疫已生效却仍被怯战压住」；控制被解除后，同一次行动里的普通攻击照常打出，不再出现「怯战已解除却仍报无法普攻」。","【乘间击隙】：与指挥型增伤冲突时仍照常叠层，第 3 次照常对敌军群体出伤并清空层数；它与击势（被动）、主动战法的增伤互不冲突，关银屏同时携带击势 + 乘间击隙时三条增伤可以并存。","【一夫当关】：减伤不再固定 50%，改为随防御属性成长 —— 防御 80 时为 50%，每点防御 +0.375%，防御 200 时约 95%（前 2 回合、仅前锋位照旧）。","【始计】：只有前 4 回合生效 —— 第 5 回合起不再出现「发动【始计】」，也不会再因为受到伤害进入洞察；前 4 回合的增伤、减伤与洞察照旧。","再次发动也算一次发动：刘禅【赐剑长驱】、正始之变等让队友当场再发动一次战法的效果，现在完整走「发动战法之后」的结算 —— 宝物【金鸠·鸠佑】的增伤照常叠层、马岱【奉令护蜀】照常叠层、【乘间击隙】照常计次，不会再「两次战法只算一次」。","【乘间击隙】的详细战报：满 3 层发动的那次群体攻击现在会显示「发动【乘间击隙】」并带伤害明细，不再只有统计里有数字、详细战报里翻不到。"]},{kind:"说明",items:["免疫控制只解除「控制类」效果（混乱 / 暴走 / 怯战 / 犹豫 / 挑衅），不会清除灼烧、恐慌等持续伤害。","【乘间击隙】满 3 层的那次群体攻击官方写作「攻击」，因此会吃到自身攻击增伤层的加成。","以上改动会改变相关阵容的伤害数值，历史战报不会重算。"]}]},{version:"1.13",date:"2026-10-19",title:"百家词条战法化 + 陆抗加强 + 三处机制修复",summary:"本版把百家武将的 21 条词条做成可直接装配的普通战法，战法背包新增「百家」分类并按武将分组；陆抗【西陵克晋】两段伤害提升到 180%；同时修复暴走普攻、酒池肉林与帝临回光、长弓兵先发三处问题；战报详情把准备阶段加成拆成四类标题、补上每回合的回合前阶段标题，并按阵营给武将名分色。",groups:[{kind:"新增",items:["战法背包新增「百家」分类：按武将分组展示 21 条百家词条（张恭、朱士行、麦子、九色鹿、陶渊明），可直接装配到普通战法槽，不需要副将机制。","百家战法按武将原主战法名显示，红色标签显示具体词条；例如张恭一行是「西陲立功 · 靖边 / 挫锐 / 选锋 / 振旅 / 坚壁」，其中靖边发动率为 50%。"]},{kind:"优化",items:["陆抗【西陵克晋】：攻击与谋略两段基础伤害率由 150% 提升到 180%，满级描述同步更新；1 级描述为 90%。","战报详情：准备阶段把阵营加成、称号加成、兵种加成、兵种特性加成拆成独立标题；兵种特性按武将列出专属与已选通用特性。","战报详情：每回合行动前的事件单独显示「回合前阶段」标题；红方武将名显示红色、蓝方武将名显示绿色，回合事件里也能看出阵营。","战报详情：准备阶段不再显示「出手顺序」一行，避免与左侧回合轨重复。"]},{kind:"修复",items:["暴走普攻：当攻击距离内没有敌军时，暴走武将现在会照常攻击范围内的友军，不再空转；同侧目标距离按压缩后的站位计算。","酒池肉林：第 3 回合的「造成伤害大幅降低」改为晚于同回合的延迟指挥效果结算，避免己方灵帝【帝临回光】的恐慌伤害被冻结，整场只打出约 10%。","长弓兵「先发」：改为前 2 回合无条件优先行动，攻守双方都生效，不再只在作为防守方时生效。"]},{kind:"说明",items:["百家词条本版先以普通战法形式进入通用战法池，暂不启用副将上阵与培养机制。","战法与状态结算口径有调整，部分对局的伤害数值与出手顺序会与旧版不同。"]}]},{version:"1.12",date:"2026-10-19",title:"双将上架 + 暴走选目标与一批战法修复",summary:"本版上架两名五星武将（汉·弓「十常侍」、魏·骑「卞夫人」），把暴走的「敌我不分」扩到主动战法、治疗、增益与行动时判定的指挥战法；同时修好一批战法细节：知己知彼不再给敌人增伤、控制扩散能看见也确实多打一个目标、势无虚动的增伤用完就清、烈火焚舟补上减士气，士气增减不再互相顶掉。",groups:[{kind:"新增",items:["新武将「十常侍」（汉·弓，cost 5.5，攻击距离 4）上架：主战法「乱政」已实装，可直接进配将池与模拟对战。","「乱政」：发动后对敌军单体随机施加 动摇 / 恐慌 / 燃烧 / 妖术 / 混乱 / 犹豫 / 暴走 / 怯战 / 挑衅 / 围困 之一，持续 2 回合；该效果执行 3 次，每次的目标和效果都独立判定。","新武将「卞夫人」（魏·骑，cost 2，攻击距离 2）上架：主战法「俭仪蹈和」已实装。","「俭仪蹈和」：前 3 回合压制敌军攻击最高者（攻击 −100）与谋略最高者（谋略 −100）；敌军群体每次发动主动战法或普通攻击后，有 50% 几率使其下一回合陷入犹豫或怯战（两者随机其一）。"]},{kind:"修复",items:["暴走：暴走武将的主动战法目标改为敌我不分（敌我全体、不含自己），与普攻口径一致；未暴走单位行为不变。","暴走：治疗、增益与行动时判定的指挥战法同样敌我不分 —— 例如乐进【奋疾先登】暴走时会把群体攻击砍到队友身上；只作用于自己的效果仍作用在自己身上。","【知己知彼】：敌军侧改为「受到的伤害提高」，敌方自己出手时不会再叠「造成的伤害提高」而变成给自己增伤。","控制类战法的额外目标（小乔&大乔【双艳】等的「控制扩散」）：优先挑还没被控的敌人；只有真的多控住一个才消耗，否则留到下次；战报会写明「被【双艳】的控制扩散额外命中（新增控制 / 刷新已有控制）」。","控制类效果（混乱 / 暴走 / 怯战 / 犹豫）按包内口径「效果不叠加 · 先施加者生效」：同一控制被重复施加时不再顺延时长，战报写明「暴走已生效（先施加者生效，本次不生效）」—— 原来每命中一次就把控制再续两回合，双艳这类战法因此能长期锁人。","【势无虚动】：追击增伤在追击战法发动后即消耗，不会出现「用完不清、越叠越高」（原先只有打出伤害的追击才清）。","【烈火焚舟】：引爆时按官方文案使目标与相邻敌军士气降低 10（原先未实现，战报也不显示）。","士气：降低与提高都不再和其他效果冲突，多来源逐条相加（原先同为主动战法的两条士气降低会互相顶掉）。"]},{kind:"说明",items:["本版合并了此前三条未上线的更新（卞夫人上架、暴走选目标两处修复），版本号沿用 1.12。"]}]},{version:"1.11",date:"2026-10-17",title:"手机端界面精简 + 一批战法与战报修复",summary:"手机端把几处占地方的内容收了起来：武将详情的宝物槽缩小并回到画像正下方；顶栏不再显示 AI配将 与设置，底栏不再显示随机种子与最大回合。桌面端保持原样。同一版还修复了一批战法与战报问题：作用范围、减伤与叠层、额外目标、成长率、伤害明细、出手与准备时序。",groups:[{kind:"优化",items:["手机端武将详情的宝物槽改为跟随画像宽度：未佩戴时收成小方块、落在画像正下方，不再压住右侧的兵种说明","手机端顶栏收起「AI配将」与设置入口，底栏收起「随机种子」「最大回合」两项调试信息，给配将与「开始模拟」留出更多空间"]},{kind:"修复",items:["修复【法正】「难知如阴」与【田丰】「尽言直谏」的作用范围：现在只作用于被点名的那个战法（难知如阴在第 3、5、7 回合按官方口径转为友军全体），不再把目标身上全部主动、追击战法一起加强","修正「避锐」减伤的结算：并入增减伤总和统一计算、受击时逐层消耗，不再单独乘算导致与面板数值对不上","修复宝物技能「济世」的叠层与消耗：每次恢复叠 1 层减伤、可以一直叠加，受到下一次伤害时一次性全部清空（那一次伤害仍吃满全部层数）","修复宝物【元戎】「迸发」的额外目标：只在首次发动追击主战法后追加一次，且两次追击可以是同一个目标","修复战报伤害明细的两处显示问题：妖术诅咒 / 引燃 / 动摇不再统一显示成「恐慌」；减伤明细会区分「攻击伤害」与「伤害」","修正出手顺序：同速同站的武将不再固定红方先出手，改由中立随机决定（只影响完全同速同站的情况）；长弓兵「先发」改为只在作为防守方时生效；已经到期的速度增益不再影响当回合排序","修正准备战法的时序：释放不再重复算一次「试图发动」（令无空悬 / 兵者诡道 不会因为释放再叠一层），但释放前会照常走一次「运筹决胜」这类发动前判定；跳过准备仍只对「需要准备的主战法」生效","修正【步诸葛】「诸葛锦囊」的成长率：造成伤害提升改为随谋略成长（每点 0.1），不再是一个固定值"]},{kind:"说明",items:["界面调整只作用于手机端（窄屏或触屏横屏）；桌面端保持原样，AI配将与设置仍可从顶栏进入","战法与战报的修复属于结算口径修正：部分对局的伤害数值、行动与准备时序会与旧版不同"]}]},{version:"1.10",date:"2026-10-16",title:"修复两处效果异常：规避叠加与避锐累积",summary:"修复了两个会让战斗强度失真的效果问题：【孙权】的「九锡黄龙」连续发动时，规避会被反复叠加，使全队近乎免疫所有伤害；【疲兵沮意】的「避锐」层数会跨回合无限累积，令减伤长期停在高位。两处现已按官方口径结算。",groups:[{kind:"修复",items:["修复【孙权】主战法「九锡黄龙」重复发动时规避异常叠加的问题：同一目标身上只保留一份规避、先施加者生效，效果为「免疫接下来受到的 2 次伤害」，不再随发动次数增长","修复【疲兵沮意】「避锐」层数跨回合累积、减伤长期维持在高位的问题：现在每回合按官方文案叠加为 2 层（上限 2 层），受击时逐层消耗","【疲兵沮意】每层减伤按官方拆分攻击、策略两档分别结算，对策略伤害的减伤不再沿用攻击档数值"]}]},{version:"1.9",date:"2026-10-16",title:"新增许褚、陈寿特性与热门预设，战斗加入战法觉醒",summary:"魏国 5 星武将【许褚】与他的主战法「裸衣鏖战」登场；【千机谋变】【神锋破巧】【形兵列阵】【未雨绸缪】四套战法可学习使用；【河内世泽】开放觉醒，觉醒后效果按 15 级计算。本次同时上线「陈寿特性」—— 17 条赛季特色特性可给单个武将佩戴；以及「热门预设」内置热门配队；并修正了宝物词条「逐胜」等几处效果。",groups:[{kind:"新增",items:["新增 5 星武将【许褚】（魏·步）：主战法「裸衣鏖战」会挑衅攻击最高的敌军，受到挑衅目标伤害时反击，并持续压制其攻击属性","新增可学习战法【千机谋变】：准备 1 回合，对敌军单体连续发动 4~6 次策略攻击，每次攻击重新判定目标","新增可学习战法【神锋破巧】：对敌军单体造成高倍率攻击伤害，并大幅降低其谋略属性","新增可学习战法【形兵列阵】：我方三名武将兵系互不相同时，分别强化前锋、中军、大营","新增可学习战法【未雨绸缪】：让自身下一次造成策略伤害的主动战法可以再发动一次","新增「战法觉醒」：觉醒后的战法效果按 15 级计算，目前支持【河内世泽】","新增「陈寿特性」：共 17 条赛季特色特性，在武将详情页的「陈寿特性」格给单个武将佩戴；一名武将仅能使用一种，可随时更换","陈寿特性的数值取自官方区间、由你自选：精进 / 昂扬 / 审慎为 4%~10%（默认 5%），砥砺总计 6~12 点可自行分配到攻击、防御、谋略、速度","【陈寿·出师·持重 / 争先】按官方逐武将表调整统率（±0.5），并同步提升该武将攻击、防御、谋略的初始值与成长率（速度与攻城不变）","新增「热门预设」：内置一批热门配队，可一键上场、设为木桩，或「另存为我的预设」后自行修改；内置预设不占用你的预设条数"]},{kind:"修复",items:["修正宝物词条【逐胜】的效果：由原先的对所有目标增伤，改为只对兵力最低的敌军增伤","修正宝物词条【英勇】【善谋】【筹算】等按战法类型判定的效果，在部分主战法上不生效的问题","修正【疲兵沮意】的避锐效果：避锐改为每回合开始时刷新为 2 层（不再跨回合累积），每次受到的伤害消耗 1 层并按其减免；受到的攻击伤害与策略攻击伤害分别按各自的减伤数值结算"]},{kind:"调整",items:["【迟智难酬】的发动率由 35% 调整为 40%","【河内世泽】补全司马懿专属效果：司马懿发动后，自身受到的伤害降低，持续 1 回合"]}]},{version:"1.8",date:"2026-10-15",title:"修正战报里持续伤害的归属与增减伤说明",summary:"战报中持续伤害（恐慌、燃烧、妖术诅咒等）此前会记在承受伤害的一方名下，现在改为正确记在施加者名下；增减伤状态也会写明限定的是攻击还是策略。",groups:[{kind:"修复",items:["战报里持续伤害的造成者改为显示正确的施加者，之前会错误地显示成承受伤害的一方。","增减伤状态写明伤害类型：「造成的策略攻击伤害提高」与「造成的伤害提高」不再混同显示。"]}]},{version:"1.7",date:"2026-10-15",title:"修复「久战熟谋」的谋略加成没有生效",summary:"「久战熟谋」的每层增益之前一直按基础值 5% 计算，没有随携带者的谋略提高。修好后它会正常随谋略增长。",groups:[{kind:"修复",items:["「久战熟谋」每层的策略伤害提高现在随携带者的谋略属性增长，在此之前它恒定为基础值 5%。"]}]},{version:"1.6",date:"2026-10-15",title:"按游戏内实际数值校正一批战法的距离与发动率",summary:"对照游戏客户端里的战法数据，把 40 个战法的有效距离、发动概率和准备回合改成与游戏内一致。有的战法之前打不到本该打到的目标，有的发动率偏低或偏高。",groups:[{kind:"调整",items:["37 个战法的有效距离改为与游戏内一致：玄武洰流、白衣渡江、奋疾先登、奇兵拒北等能打得更远，名士在野、西乡武功、难知如阴等相应缩短。"]},{kind:"修复",items:["8 个战法的发动概率改为满级数值，例如玄武洰流 40%→35%、樊渊泅囚 35%→40%、上将潘凤 40%→80%、明慧通透 40%→60%。","「未笄难言」改为需要 1 回合准备。"]}]},{version:"1.5",date:"2026-10-14",title:"称号按三人组生效，并修正几处战法结算",summary:"称号改为按解包里的三人组合判定，凑齐其中一组就给全队加属性。庞统、司马懿和计险远近的几处算错也一并改了。百家副将的词条效果已经能进战斗，配将界面还不能点选。",groups:[{kind:"新增",items:["称号按三人组生效：凑齐解包登记的一组武将，全队就吃到对应属性。同一称号可以换合法替补（例如魏之智换成程昱）；同名的两张不同卡不算凑齐。"]},{kind:"修复",items:["庞统「密谋定蜀」、张梁「人公将军」、始计：降低的是对方打出去的伤害，不再降低对方受到的伤害。","司马懿「其徐如林」：友军打出的相邻跳伤记进司马懿自己的战法统计。","计险远近等「本回合」的增减伤，会在回合结束时清掉，不再留到后面的回合。"]},{kind:"说明",items:["百家副将（朱士行、张恭、麦子、九色鹿、陶渊明）的词条效果已经进入战斗结算。配将界面还不能点选副将。"]}]},{version:"1.4",date:"2026-10-10",title:"对手池：固定对手扩到 8 支 + 每一条都能开关",summary:"对手池里的固定测试集从 1 支扩到 8 支，其中 4 支是从实战截图识别回来的敌方队；同时每一条对手（固定的和你自己加的）右侧都多了一个开关 —— 关掉的队伍留在池子里，只是不参与胜率比较。",groups:[{kind:"新增",items:["对手池固定测试集扩到 8 支：新增 4 支实测敌方队（太史慈张春华周泰 / 太史慈曹植关羽 / 祝融夫人陆抗曹操 / 荀彧张春华曹操），站位、等级与三个战法按实战截图原样录入，打开对手池就能看到。","对手池「参战开关」：每条对手右侧一键切换参战 / 已关，关掉的整条灰掉划掉、留在池子里随时能开回来；标题行会写「参战 N · 已关 M」。AI配将的胜率搜索与对拍只用开着的那些，点开关不用再确认。"]},{kind:"说明",items:["固定测试集依然删不掉（它随站发布），但现在可以逐条关掉 —— 「不想让它参与比较」不再等于「只能忍着」。已经关掉的队伍在下一次打开站点时仍然是关着的。"]}]},{version:"1.3",date:"2026-10-09",title:"声明与许可：非官方作品、素材归网易、代码 MIT",summary:"把「这是什么、素材归谁、允许怎么用」一次说清楚：底栏多了「声明」入口，第一次打开页面也会先提示一次；仓库里同时补上了完整声明条款（NOTICE.md）与代码许可（MIT）。玩法与数值没有任何改动。",groups:[{kind:"新增",items:["底栏「声明」：随时可查本项目是什么、素材归谁、允许怎么用；第一次打开页面会先提示一次，之后不再打扰（想看再点底栏）。"]},{kind:"说明",items:["本项目是玩家自制的非官方作品，与网易公司及其关联方没有任何关系，也未获其授权：它不是游戏客户端、私服或外挂，不提供任何游戏服务，也不冒充官方客户端。","武将立绘、官方标识、战法文案与数值等素材，版权归权利方所有，不适用本项目的 MIT 许可证 —— MIT 只覆盖本项目自己编写的代码；素材请勿再分发、勿用于商业用途，也勿用于训练模型或构建数据集。","严禁任何形式的盈利（售卖、付费下载或分发、收费服务器或收费代开、广告 / 打赏 / 会员 / 赞助等）；权利人如认为本项目侵犯其权益，可通过仓库 Issue 联系，我们会立即删除或下架相关内容。完整条款与素材清单见仓库根目录的 NOTICE.md。"]}]},{version:"1.2",date:"2026-10-06",title:"AI配将·对手池对拍 + 合回配将台 + 连击分兵时长修正",summary:"AI配将多了一套「对手池」：固定测试集（随站发布）加上你自己导入的队伍，可以让它把一套阵容在整份池子上打一遍，逐个对手看胜率与伤害。AI配将也收回配将台，两边来回切换不再打断正在跑的一轮。",groups:[{kind:"新增",items:["AI配将「对手池」：固定测试集随站发布（首批 1 支实测对手队，之后继续扩充），也能把阵容预设导进去；点开就能看到每支对手的构成，加入 / 移出都要再确认一次。","AI配将「打对手池 / 胜率搜索 / 前后对比」：一句话让它把当前阵容在整份池子上打一遍 —— 逐对手给出胜率、平局率与场均八回合总伤、前三回合伤害、控制人回合；要找最优就两段式搜（粗筛 + 决赛，一次最多动两个空位），想稳就按「最差对手胜率」排序。","配将台 ↔ AI配将 现在是同一页的两个房间：来回切不打断正在跑的一轮，顶栏入口带金点提示「还在跑」；安卓返回键按 AI配将 → 伤害测试实验室 → 战报页 → 退出 的顺序走。"]},{kind:"优化",items:["AI配将更快更省：第一轮只发当下必需的几个工具，之后按问题需要再开档 —— 同一批问题的通过率不变，token 约省四分之一、真跑场次约省三分之一；工具调用行末尾会写明这一轮的档位与工具数。","AI配将的数字更好追：表格里重复出现的数值同样标注来源；碰到「已下架战法」「控制型在木桩口径量不出」这类边界，会先把口径说清楚再答。","截图导入队伍：同名武将（例如吕布的几个版本）不再猜，直接提示按版本选。"]},{kind:"修复",items:["修好了连击 / 分兵类效果会多覆盖一个回合的问题：长兵方阵等「前 N 回合」效果不再拖到第 5 回合还在生效。"]},{kind:"调整",items:["三术奇谋的「攻击 / 防御 / 谋略下降」现在随施法者谋略提高（实测反解成长率 0.075/点）—— 该战法重新上架，可以正常配装。"]}]},{version:"1.1",date:"2026-09-29",title:"AI配将独立成页 + 全局设置",summary:"「AI 顾问」改名「AI配将」并搬进独立页面：主站顶栏只留入口，功能按需展开；配置接口与密钥的入口统一收进「设置」。",groups:[{kind:"新增",items:["AI配将独立页（顶栏第 7 项进入）：极简单栏为底，左上角一键展开左侧栏，变成「阵容 / 功能 / 最近一轮」常驻的工作台；开或关记在本机，刷新不丢。","设置：接口地址 / 模型 / 密钥、额度与长搜索确认阈值、严格按 box 推荐、数据清理（跑批缓存 / 会话 / 偏好档案 / box）。主站顶栏齿轮与 AI配将 页内打开的是同一个。","AI配将 页内三个按需面板：我的 box（截图识图建档）、偏好档案、历史与证据 —— 点按键才出现，不再常驻页面。","工具调用过程行：默认收起成一行（次数 / 场次 / 耗时），点开逐条看明细与缓存标记。"]},{kind:"优化",items:["对话操作：Enter 发送、Shift+Enter 换行（中文输入法回车不误发）、Esc Esc 停止；窄屏下侧栏改浮层，点空白或右上「×」收起。","AI配将 与主站共用同一份队伍：从主站进入时自动交接，方案「应用」写回后主站即时同步。"]},{kind:"调整",items:["原「AI 顾问」右侧抽屉退役，功能等价迁入独立页；主站只保留一个入口。","密钥只存在于「设置」：主站首屏与 AI配将 页面上不再出现任何密钥 / 接口地址控件。"]}]},{version:"1.0",date:"2026-09-28",title:"首个公开版本",summary:"主站正式立版：从配将、战法到逐回合战报与打桩实验室全线打通。今后每次上线的新改动，都会在这里按版本公布。",groups:[{kind:"新增",items:["配将台：红队 / 蓝队各三将（大营 · 中军 · 前锋）。武将池支持中文名与拼音搜索（lb → 吕布、刘备）、势力与兵种筛选，拖拽或点选即可上阵，队内换位、跨队调人、拖回池子卸下都支持。","武将详情：自由属性点分配（攻击 / 防御 / 谋略 / 速度）、40~50 级与红度调整、携带兵力自动重算；二级兵种转换与兵系特性、宝物与锻造词条一并可选。","战法库：按品级（S / A / B / C）与类别（被动 / 指挥 / 主动 / 追击）筛选，也可直接搜战法名，查看满级与 1 级描述。","战报三视图：简略（双方名册 + 兵力条 + 胜负印章）、统计（战法发动次数与杀伤、武将伤害 / 恢复 / 控制占比）、详情（逐回合事件流，含士气几率与增减伤来源）。","伤害测试实验室：自定义木桩侍卫的四维 / 兵力 / 兵种与三个 D 级战法，一键模拟十次或五十次，输出伤害占比饼图与标准差、变异系数、中位数等统计。","阵容预设：把队伍存成预设（编号 + 命名 + 搜索），一键上场到红队或蓝队，也能直接设为实验室的木桩队伍。","统计胜率：同一套阵容跑 200 场（每颗种子正反各跑一场，抵消先手偏向），先给胜 / 平 / 负概率再看细节。","引擎使用指南：七步图文教程，从配将一路看到详细战报。","支持装到手机上：主站是 PWA，可添加到桌面离线打开；也有安卓壳版本。"]},{kind:"说明",items:["随机种子由系统自动生成，每次点「开始模拟」都不一样，底栏只做展示。","最大回合固定 8 回合；双方士气默认 120（可在 80~140 之间调），士气越高战法发动率越高。","携带兵力 = 等级 × 100 + 5000 + 红度 × 200：40 级白板 9000，50 级满红 11000。","兵种相克按骑克步、步克弓、弓克骑结算：被克制方打克制方时伤害降低 30%。"]}]}],X=nn[0].version,sn="stzb_site_version_seen",an="stzb_site_version_notified";function Nt(e){return e.split(".").map(t=>Number(t))}function rn(e,t){const n=Nt(e),s=Nt(t),a=Math.max(n.length,s.length);for(let r=0;r<a;r+=1){const o=(n[r]??0)-(s[r]??0);if(o!==0)return o}return 0}function Ja(e){return e.groups.reduce((t,n)=>t+n.items.length,0)}const Za={新增:"add",优化:"polish",修复:"fix",调整:"tune",说明:"note"};function he(e){return e.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function Qa(e){return e.map((t,n)=>{const s=t.groups.map(a=>`
